SELECT COUNT(*)
FROM reservation
WHERE room_id = #{roomId}
  AND status IN ('PENDING', 'APPROVED')
  AND start_time < #{endTime}
  AND end_time > #{startTime}

SELECT id, member_id, room_id, start_time, end_time, purpose, status, created_at, updated_at
FROM reservation
WHERE id = #{id}

mapper.update:
UPDATE reservation
SET status = 'CANCELED'
WHERE id = #{id}
  AND member_id = #{memberId}
  AND status IN ('PENDING', 'APPROVED')
  AND start_time > #{now}
